142	    public void setMembershipNumber(String membershipNumber) {
143	        this.membershipNumber = membershipNumber;
144	    }
145	
146	    /**
147	     * A stable, normalised key identifying this owner's household (same last name
148	     * and address). The last name is folded case- and whitespace-insensitively and
149	     * the address is reduced to its canonical form exactly as in
150	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
151	     * household.
152	     *
153	     * @return the household key
154	     */
155	    public String householdKey() {
156	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
157	    }
158	
159	    /**
160	     * Whether this owner belongs to the same household as {@code other}: that is,
161	     * they share the same last name and address. The last name is compared
162	     * case-insensitively with runs of whitespace collapsed to a single space (and
163	     * surrounding whitespace trimmed); the address is compared in its canonical
164	     * normalised form (see {@link #normalizeAddress(String)}).
165	     *
166	     * @param other the owner to compare against
167	     * @return {@code true} if both owners share a household
168	     */
169	    public boolean sameHouseholdAs(Owner other) {
170	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
171	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
172	    }
173	
174	    /**
175	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
176	     * trim, collapse internal runs of whitespace to a single space and lower-case.
177	     */
178	    private static String normalize(String value) {
179	        if (value == null) {
180	            return "";
181	        }
182	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
183	    }
184	
185	    /**
186	     * Reduce an address to its canonical stored form: trim and collapse runs of
187	     * whitespace to a single space, upper-case, and expand common abbreviations
188	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
189	     * they appear as whole words. The result is what is stored, returned and used
190	     * for every household comparison; it is idempotent, so re-normalising an
191	     * already-normalised address leaves it unchanged.
192	     *
193	     * @param value the raw address (may be {@code null})
194	     * @return the normalised address, or the empty string if {@code value} is
195	     *         {@code null} or blank
196	     */
197	    public static String normalizeAddress(String value) {
198	        if (value == null) {
199	            return "";
200	        }
201	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
202	        if (collapsed.isEmpty()) {
203	            return "";
204	        }
205	        String[] tokens = collapsed.split(" ");
206	        for (int i = 0; i < tokens.length; i++) {
207	            tokens[i] = switch (tokens[i]) {
208	                case "ST" -> "STREET";
209	                case "RD" -> "ROAD";
210	                case "AVE" -> "AVENUE";
211	                default -> tokens[i];
212	            };
213	        }
214	        return String.join(" ", tokens);
215	    }
